import{_t as e,it as t,n,rt as r}from"./chunks/framework.CJEq1BAB.js";var i=JSON.parse(`{"title":"Operations","description":"","frontmatter":{"title":"Operations","covers":{"screens":[],"stories":[]}},"headers":[],"relativePath":"administration/operations.md","filePath":"administration/operations.md"}`),a={name:`administration/operations.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to “Operations”">​</a></h1><h2 id="database-roles" tabindex="-1">Database roles <a class="header-anchor" href="#database-roles" aria-label="Permalink to “Database roles”">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Used by</th><th>Owns</th></tr></thead><tbody><tr><td><code>oea_owner</code></td><td>migration step: <code>db/migration</code>, <code>db/migration-audit</code></td><td>schemas <code>public</code>, <code>audit</code> and their objects</td></tr><tr><td><code>oea_reporting_owner</code></td><td>migration step: <code>db/migration-reporting</code></td><td>schemas <code>reporting</code>, <code>reporting_ctx</code> and their objects</td></tr><tr><td><code>oea_app</code></td><td>backend at runtime</td><td>nothing</td></tr><tr><td><code>oea_audit_cleanup</code></td><td>audit retention job</td><td>nothing</td></tr><tr><td><code>oea_auditor</code></td><td>audit verification, external auditors</td><td>nothing</td></tr><tr><td><code>oea_analytics</code></td><td>raw analytics connections</td><td>nothing</td></tr></tbody></table><p>No role is <code>SUPERUSER</code>, <code>CREATEROLE</code>, <code>CREATEDB</code> or <code>BYPASSRLS</code>, and no OEA role is a member of another OEA role. The runtime role <code>oea_app</code> holds only <code>INSERT</code> and <code>SELECT</code> on the audit tables; the backend refuses to start otherwise. You rotate role passwords by running the provisioning script again (see <a href="./../setup/installation#provisioning-once">Installation</a>).</p><h2 id="request-size-limits" tabindex="-1">Request size limits <a class="header-anchor" href="#request-size-limits" aria-label="Permalink to “Request size limits”">​</a></h2><p>Request bodies are limited before they are parsed. A larger body is answered with <code>413</code> and the problem type <code>urn:oea:problem:request-too-large</code> (<code>package-too-large</code> for metamodel packages):</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Applies to</th></tr></thead><tbody><tr><td><code>oea.web.request-size.default</code> (<code>OEA_WEB_REQUESTSIZE_DEFAULT</code>)</td><td><code>1MB</code></td><td>every operation with a request body</td></tr><tr><td><code>oea.web.request-size.entity-batch</code> (<code>OEA_WEB_REQUESTSIZE_ENTITYBATCH</code>)</td><td><code>10MB</code></td><td><code>POST /entities/batch</code></td></tr><tr><td><code>oea.metamodel.import.max-size</code> (<code>OEA_METAMODEL_IMPORT_MAXSIZE</code>)</td><td><code>10MB</code></td><td><code>POST /admin/metamodel/import</code></td></tr></tbody></table><p>A reverse proxy in front of OEA should allow at least the largest of these values.</p><h2 id="key-encryption-key" tabindex="-1">Key-encryption key <a class="header-anchor" href="#key-encryption-key" aria-label="Permalink to “Key-encryption key”">​</a></h2><p>Stored secrets – TOTP secrets and client secrets of identity providers – are encrypted with AES-256-GCM under the key-encryption key, a file outside the database. Every encrypted value records the ID of its key (the first 16 hex digits of the key&#39;s SHA-256).</p><ul><li><code>oea.security.kek.current</code> (<code>OEA_SECURITY_KEK_CURRENT</code>) names the key file; the Compose setup mounts the file named by <code>OEA_KEK_FILE</code> as the secret <code>/run/secrets/oea_kek</code>.</li><li>Keep the key out of database backups and store it separately. A database dump without the key does not reveal the secrets – and without the key, the secrets are lost.</li></ul><h3 id="rotate-the-key" tabindex="-1">Rotate the key <a class="header-anchor" href="#rotate-the-key" aria-label="Permalink to “Rotate the key”">​</a></h3><ol><li><p>Create a new key file and configure it as <code>oea.security.kek.current</code>; configure the old one as <code>oea.security.kek.previous</code> (a list of files, <code>OEA_SECURITY_KEK_PREVIOUS</code>).</p></li><li><p>Re-encrypt all stored secrets with the runtime credentials:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oea-backend.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reencrypt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --spring.datasource.url=jdbc:postgresql://db.example.org:5432/oea</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --spring.datasource.username=oea_app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --spring.datasource.password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_APP_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.security.kek.current=/run/secrets/oea_kek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.security.kek.previous=/run/secrets/oea_kek_previous</span></span></code></pre></div></li><li><p>Remove the old key from the configuration and destroy it.</p></li></ol><p>The command re-encrypts in one transaction and prints <code>OK &lt;n&gt; secret(s) re-encrypted with key &lt;key ID&gt;</code>. Exit codes: <code>0</code> done, <code>1</code> a value could not be decrypted with the configured keys (nothing was changed), <code>2</code> usage or connection error.</p><h2 id="verify-the-audit-trail" tabindex="-1">Verify the audit trail <a class="header-anchor" href="#verify-the-audit-trail" aria-label="Permalink to “Verify the audit trail”">​</a></h2><p>Every audit record is a link of a hash chain computed by the database. The verification command recomputes the chain with the read-only role <code>oea_auditor</code>:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oea-backend.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.audit-verify.url=jdbc:postgresql://db.example.org:5432/oea</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.audit-verify.password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_AUDITOR_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --checkpoints=/var/log/oea/backend.log</span></span></code></pre></div><p>With Compose: <code>docker compose run --rm migrate audit verify --oea.audit-verify.url=jdbc:postgresql://postgres:5432/oea --oea.audit-verify.password=…</code>. The environment variables <code>OEA_AUDITVERIFY_URL</code> and <code>OEA_AUDITVERIFY_PASSWORD</code> work as well.</p><table tabindex="0"><thead><tr><th>Exit code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>chain intact (<code>OK &lt;links&gt; links, head &lt;chain_seq&gt; &lt;hash&gt;</code>)</td></tr><tr><td><code>1</code></td><td>first broken link, missing link, or a database head behind or diverging from a checkpoint (<code>BROKEN …</code>)</td></tr><tr><td><code>2</code></td><td>usage or connection error</td></tr></tbody></table><p><strong>Checkpoints</strong>: the backend appends a checkpoint every 60 minutes (<code>oea.audit.checkpoint-interval</code>, 5–1440 minutes) and at orderly shutdown, and writes a log line <code>event=audit.checkpoint chainSeq=… recordHash=… at=…</code>. Keep the backend log outside the database host (log shipper, journald, SIEM): checkpoints are only as trustworthy as the place they are stored. Pass the log file with <code>--checkpoints=</code> to detect deleted newest records or a restored older backup.</p><h2 id="upgrade-postgresql-to-a-new-major-version" tabindex="-1">Upgrade PostgreSQL to a new major version <a class="header-anchor" href="#upgrade-postgresql-to-a-new-major-version" aria-label="Permalink to “Upgrade PostgreSQL to a new major version”">​</a></h2><p>The Compose setup uses PostgreSQL 18. Data directories are not compatible across major versions, so a major upgrade needs a dump and restore or <code>pg_upgrade</code>:</p><ol><li>Stop the backend, keep PostgreSQL running, and dump the database as superuser: <code>pg_dumpall</code> (roles and data) or <code>pg_dump -Fc oea</code> plus the provisioning script for the roles.</li><li>Start the new PostgreSQL version on an empty volume; the provisioning script creates the roles again.</li><li>Restore the dump, then run the migration step and start the backend.</li></ol><p>Since PostgreSQL 18, the official image keeps its data in <code>/var/lib/postgresql/18/docker</code>; the Compose volume is therefore mounted at <code>/var/lib/postgresql</code>. The minimum supported version stays PostgreSQL 15; the backend checks it at startup.</p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};